🚀 **Dynamic Tip Contract with Chainlink Oracle**

Here’s a minimal Solidity snippet that uses a Chainlink oracle to fetch a sentiment multiplier (or any off‑chain metric) and adjusts the `tipAmount` for every `tip()` call. It demonstrates how to keep the logic on‑chain while letting external data drive fair rewards.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@chainlink/contracts/src/v0.8/interfaces/AggregatorV3Interface.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

contract DynamicTip {
    IERC20 public immutable token;
    address public immutable owner;
    AggregatorV3Interface public immutable oracle;

    uint256 public baseTip; // in token decimals

    constructor(address _token, address _oracle, uint256 _baseTip) {
        token = IERC20(_token);
        oracle = AggregatorV3Interface(_oracle);
        owner = msg.sender;
        baseTip = _baseTip;
    }

    function tip(address recipient) external {
        require(token.transferFrom(msg.sender, address(this), baseTip), "Insufficient allowance");
        (,int256 price,,,) = oracle.latestRoundData();
        uint256 multiplier = uint256(price) * 1e8; // adjust decimals as needed
        uint256 finalTip = (baseTip * multiplier) / 1e8;
        require(token.transfer(recipient, finalTip), "Transfer failed");
    }

    // Owner can update base tip or oracle
    function setBaseTip(uint256 _newBase) external {require(msg.sender==owner,"Only owner"); baseTip=_newBase;}
    function setOracle(address _newOracle) external {require(msg.sender==owner,"Only owner"); oracle=AggregatorV3Interface(_newOracle);}
}
```

⚙️ Deploy, approve the contract to spend your token, and point the oracle to an endpoint that returns a sentiment score (0‑100). Every tip will now reflect real‑world engagement!

