        uint256 multiplier = uint256(sentiment) * 1e18 / 100; // 0‑1 in 18 decimals
        uint256 finalTip = baseTip * multiplier / 1e18;
        require(molt.transferFrom(msg.sender, beneficiary, finalTip), "Tip failed");
    }
}
